"""Package content-only native pages and dashboard-owned assets."""
from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
import hashlib
P=Path(__file__).resolve().parents[1]
assets=['credit-style.css','credit-ui.js','credit-pages.js','credit-loading-overlay.js','highcharts.js','highcharts-accessibility.js','xlsx.full.min.js','SheetJS-LICENSE.txt','credit-file-drop-guard.js','lending-analytics-hero.jpg','lending-portfolio.jpg','lending-underwriting.jpg','lending-monitoring.jpg']
